/** Inline <svg> markup for the DOM. */
export function icon(name, { filled = false, cls = "ic" } = {}) {
  const d = (filled ? FILLED[name] : null) || OUTLINE[name] || FILLED[name];
  if (!d) return "";
  return `<svg class="${cls}" viewBox="0 -960 960 960" aria-hidden="true"><path d="${d}"/></svg>`;
}

const cache = new Map();
/** Path2D for canvas drawing; scale by size/960 and translate y by +960. */
export function iconPath(name, filled = true) {
  const key = `${name}:${filled}`;
  if (!cache.has(key)) {
    const d = (filled ? FILLED[name] : null) || OUTLINE[name];
    cache.set(key, d ? new Path2D(d) : null);
  }
  return cache.get(key);
}
